def compute(vars):
    old_zyla = vars["v1"]
    new_zyla = vars["v2"]
    old_total = vars["v3"]
    new_total = vars["v4"]

    zyla_decrease = old_zyla - new_zyla
    total_decrease = old_total - new_total

    if total_decrease == 0:
        return None

    value = (zyla_decrease / total_decrease) * 100
    return {
        "value": value,
        "trace": {
            "zyla_decrease": zyla_decrease,
            "total_revenue_decrease": total_decrease,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
